protected void addPathFile(File pathComponent) throws IOException {
    if (!pathComponents.contains(pathComponent)) {
        pathComponents.addElement(pathComponent);
    }
    if (pathComponent.isDirectory()) {
        return;
    }

    String manifestClasspath = getManifestClasspath(pathComponent);
    if (manifestClasspath == null) {
        manifestClasspath = "";
    }

    if (!"".equals(manifestClasspath)) {
        processManifestClasspath(pathComponent, manifestClasspath);
    }
}

/**
 * Retrieves the CLASS-PATH value from the manifest of a JAR file.
 * Uses caching to avoid redundant file access.
 *
 * @param pathComponent the jar file to inspect
 * @return the class path value from the manifest, or null if none exists
 * @throws IOException if the jar file cannot be read
 */
private String getManifestClasspath(File pathComponent) throws IOException {
    String key = getJarCacheKey(pathComponent);
    String cached = pathMap.get(key);
    if (cached != null) {
        return cached;
    }

    JarFile jarFile = null;
    try {
        jarFile = new JarFile(pathComponent);
        Manifest manifest = jarFile.getManifest();
        if (manifest == null) {
            return null;
        }
        String classpath = manifest.getMainAttributes()
                .getValue(Attributes.Name.CLASS_PATH);
        pathMap.put(key, classpath == null ? "" : classpath);
        return classpath;
    } finally {
        if (jarFile != null) {
            jarFile.close();
        }
    }
}

/**
 * Constructs a cache key based on the jar file path, last modified time, and size.
 */
private String getJarCacheKey(File pathComponent) {
    return pathComponent.getAbsolutePath()
            + pathComponent.lastModified() + "-" + pathComponent.length();
}

/**
 * Parses and processes each entry from the manifest Class-Path attribute.
 */
private void processManifestClasspath(File pathComponent, String manifestClasspath)
        throws IOException {
    URL baseURL = FILE_UTILS.getFileURL(pathComponent);
    StringTokenizer st = new StringTokenizer(manifestClasspath);

    while (st.hasMoreTokens()) {
        String classpathElement = st.nextToken();
        URL libraryURL = new URL(baseURL, classpathElement);

        if (!"file".equals(libraryURL.getProtocol())) {
            log("Skipping jar library " + classpathElement
                    + " since only relative URLs are supported by this loader",
                    Project.MSG_VERBOSE);
            continue;
        }

        String decodedPath = Locator.decodeUri(libraryURL.getFile());
        File libraryFile = new File(decodedPath);
        if (libraryFile.exists() && !isInPath(libraryFile)) {
            addPathFile(libraryFile);
        }
    }
}

