    protected static void hbMakeCodeLengths(char[] len, int[] freq,
                                            int alphaSize, int maxLen) {
        final int[] heap = new int[MAX_ALPHA_SIZE * 2];
        final int[] weight = new int[MAX_ALPHA_SIZE * 2];
        final int[] parent = new int[MAX_ALPHA_SIZE * 2];

        prepareWeights(weight, freq, alphaSize);

        for (boolean tooLong = true; tooLong;) {
            tooLong = false;
            buildHuffmanTree(weight, parent, heap, alphaSize);

            recordCodeLengths(len, parent, alphaSize, maxLen, tooLong);

            if (tooLong) {
                reduceWeights(weight, alphaSize);
            }
        }
    }

    private static void prepareWeights(final int[] weight, final int[] freq,
                                       final int alphaSize) {
        for (int i = alphaSize; --i >= 0;) {
            weight[i + 1] = (freq[i] == 0 ? 1 : freq[i]) << 8;
        }
    }

    private static void buildHuffmanTree(final int[] weight, final int[] parent,
                                         final int[] heap, final int alphaSize) {
        int nNodes = alphaSize;
        int nHeap = 0;
        heap[0] = 0;
        weight[0] = 0;
        parent[0] = -2;

        for (int i = 1; i <= alphaSize; i++) {
            parent[i] = -1;
            nHeap++;
            heap[nHeap] = i;
            bubbleUp(heap, weight, nHeap);
        }

        while (nHeap > 1) {
            int n1 = extractMin(heap, weight, nHeap);
            nHeap--;

            int n2 = extractMin(heap, weight, nHeap);
            nHeap--;

            nNodes++;
            parent[n1] = parent[n2] = nNodes;

            int combinedWeight = combineWeights(weight, n1, n2);
            weight[nNodes] = combinedWeight;
            parent[nNodes] = -1;
            nHeap++;
            heap[nHeap] = nNodes;
            bubbleUp(heap, weight, nHeap);
        }
    }

    private static void bubbleUp(final int[] heap, final int[] weight, int idx) {
        int tmp = heap[idx];
        while (idx > 1 && weight[tmp] < weight[heap[idx >> 1]]) {
            heap[idx] = heap[idx >> 1];
            idx >>= 1;
        }
        heap[idx] = tmp;
    }

    private static int extractMin(final int[] heap, final int[] weight, int nHeap) {
        int min = heap[1];
        heap[1] = heap[nHeap];

        int idx = 1;
        while (true) {
            int child = idx << 1;
            if (child > nHeap) {
                break;
            }
            if (child < nHeap && weight[heap[child + 1]] < weight[heap[child]]) {
                child++;
            }
            if (weight[heap[idx]] <= weight[heap[child]]) {
                break;
            }
            heap[idx] = heap[child];
            idx = child;
        }
        heap[idx] = min;
        return min;
    }

    private static int combineWeights(final int[] weight, int n1, int n2) {
        int w1 = weight[n1] & 0xffffff00;
        int w2 = weight[n2] & 0xffffff00;
        int d1 = weight[n1] & 0x000000ff;
        int d2 = weight[n2] & 0x000000ff;
        return (w1 + w2) | (1 + (d1 > d2 ? d1 : d2));
    }

    private static void recordCodeLengths(final char[] len, final int[] parent,
                                         final int alphaSize, final int maxLen,
                                         final boolean tooLong) {
        for (int i = 1; i <= alphaSize; i++) {
            int depth = 0;
            int node = i;
            while (parent[node] >= 0) {
                node = parent[node];
                depth++;
            }
            len[i - 1] = (char) depth;
            if (depth > maxLen) {
                tooLong = true;
            }
        }
    }

    private static void reduceWeights(final int[] weight, final int alphaSize) {
        for (int i = 1; i < alphaSize; i++) {
            int w = weight[i] >> 8;
            w = 1 + (w >> 1);
            weight[i] = w << 8;
        }
    }
