/**
 * Adds context menu actions from registered modules.
 * @param popUpActions the action list to extend
 */
private void addContextActions(ActionList popUpActions) {
    final List<Action> modulesActions =
        ContextActionFactoryManager.getContextPopupActions();

    for (Action a : modulesActions) {
        if (a instanceof List) {
            JMenu m = new JMenu((Action) a);
            popUpActions.add(m);
            for (Action subAction : (List<Action>) a) {
                m.add(subAction);
            }
        } else {
            popUpActions.add(a);
        }
    }
}

