/**
 * Adds the critiques submenu if a single target exists and there are related critique items.
 * @param popUpActions the action list to extend
 * @param me the mouse event for hit detection
 */
private void addCritiquesMenu(ActionList popUpActions, MouseEvent me) {
    if (TargetManager.getInstance().getTargets().size() != 1) {
        return;
    }

    ToDoList list = Designer.theDesigner().getToDoList();
    List<ToDoItem> items = list.elementListForOffender(getOwner());
    if (items == null || items.isEmpty()) {
        return;
    }

    ArgoJMenu critiques = new ArgoJMenu("menu.popup.critiques");
    ToDoItem itemUnderMouse = hitClarifier(me.getX(), me.getY());
    if (itemUnderMouse != null) {
        critiques.add(new ActionGoToCritique(itemUnderMouse));
        critiques.addSeparator();
    }
    for (ToDoItem item : items) {
        if (item != itemUnderMouse) {
            critiques.add(new ActionGoToCritique(item));
        }
    }
    popUpActions.add(0, new JSeparator());
    popUpActions.add(0, critiques);
}

/**
 * Adds the stereotypes submenu if applicable.
 * @param popUpActions the action list to extend
 */
private void addStereotypesMenu(ActionList popUpActions) {
    Action[] stereoActions = getApplyStereotypeActions();
    if (stereoActions == null || stereoActions.length == 0) {
        return;
    }

    popUpActions.add(0, new JSeparator());
    ArgoJMenu stereotypes = new ArgoJMenu(
            "menu.popup.apply-stereotypes");
    for (int i = 0; i < stereoActions.length; ++i) {
        stereotypes.addCheckItem(stereoActions[i]);
    }
    popUpActions.add(0, stereotypes);
}

private Property buildAssociationEndInternal(final Association assoc,
        final String name, final Type type,
        final Integer[] multi, final Stereotype stereo,
        final Boolean navigable, final Boolean order,
        final AggregationKind aggregation,
        final Object changeable, final VisibilityKind visibility) {
    Property property = createAssociationEnd();
    property.setType(type);
    property.setAssociation(assoc);
    if (name != null) {
        property.setName(name);
    }
    if (navigable != null) {
        property.setIsNavigable(navigable);
        if (!(Boolean) navigable) {
            assoc.getOwnedEnds().add(property);
        }
    }
    if (aggregation != null) {
        property.setAggregation(aggregation);
    }
    if (visibility != null) {
        property.visibility = visibility;
    }
    if (multi != null) {
        if (multi[0] != null) {
            property.setLower(multi[0]);
        }
        if (multi[1] != null) {
            property.setUpper(multi[1]);
        }
    }
    if (order != null) {
        property.setIsOrdered(order);
    }
    if (changeable != null) {
        property.setIsReadOnly((Boolean) changeable);
    }
    if (stereo != null
            && property.isStereotypeApplicable(stereo)) {
        property.applyStereotype(stereo);
    }
    return property;
}

    return (Property) run.getParams().get(0);
}

private Property buildAssociationEndInternal(final Association assoc,
        final String name, final Type type,
        final Integer[] multi, final Stereotype stereo,
        final Boolean navigable, final Boolean order,
        final AggregationKind aggregation,
        final Object changeable, final VisibilityKind visibility) {
    Property property = createAssociationEnd();
    property.setType(type);
    property.setAssociation(assoc);
    if (name != null) {
        property.setName(name);
    }
    if (navigable != null) {
        property.setIsNavigable(navigable);
        if (!(Boolean) navigable) {
            assoc.getOwnedEnds().add(property);
        }
    }
    if (aggregation != null) {
        property.setAggregation(aggregation);
    }
    if (visibility != null) {
        property.setVisibility(visibility);
    }
    if (multi != null) {
        if (multi[0] != null) {
            property.setLower(multi[0]);
        }
        if (multi[1] != null) {
            property.setUpper(multi[1]);
        }
    }
    if (order != null) {
        property.setIsOrdered(order);
    }
    if (changeable != null) {
        property.setIsReadOnly((Boolean) changeable);
    }
    if (stereo != null && property.isStereotypeApplicable(stereo)) {
        property.applyStereotype(stereo);
    }
    return property;
}

