/**
 * Search for an operation by name within a given classifier's features.
 *
 * @param classifier The classifier to search within
 * @param opname     The operation name to find
 * @return The matching Feature if found, otherwise null
 */
private Feature findOperationInClassifier(Classifier classifier, String opname) {
    if (classifier == null) {
        return null;
    }
    List<Feature> features = classifier.getFeature();
    for (Feature f : features) {
        if (isOperationWithMatchingName(f, opname)) {
            return f;
        }
    }
    return null;
}

/**
 * Check if a feature is an operation with a matching name.
 *
 * @param feature   The feature to check
 * @param opname    The target operation name
 * @return true if the feature is an operation with the specified name
 */
private boolean isOperationWithMatchingName(Feature feature, String opname) {
    return feature instanceof Operation && opname.equals(feature.getName());
}

/**
 * Determine the package namespace to search for operations.
 *
 * @param context   The context object
 * @param classifier The primary classifier (if any)
 * @return The appropriate Namespace, or null if none is found
 */
private Namespace getPackageNamespace(Object context, Classifier classifier) {
    if (context instanceof UmlPackage) {
        return (Namespace) context;
    }
    if (classifier == null) {
        return null;
    }
    Namespace parent = classifier.getNamespace();
    while (parent instanceof Classifier) {
        if (parent.getNamespace() == null) {
            break;
        }
        parent = parent.getNamespace();
    }
    return parent;
}

/**
 * Search for an operation by name within owned elements of a package.
 *
 * @param pack    The namespace containing owned elements
 * @param opname  The operation name to find
 * @return The matching Feature if found, otherwise null
 */
private Feature findOperationInPackage(Namespace pack, String opname) {
    if (pack == null) {
        return null;
    }
    Collection<ModelElement> mes = pack.getOwnedElement();
    for (ModelElement me : mes) {
        if (me instanceof Classifier) {
            Classifier classifier2 = (Classifier) me;
            Feature result = findOperationInClassifier(classifier2, opname);
            if (result != null) {
                return result;
            }
        }
    }
    return null;
}

