    public void remove() {
        for (ArgoDiagram diagram : diagrams) {
            diagram.remove();
        }

        members.clear();
        if (!roots.isEmpty()) {
            try {
                Model.getUmlFactory().deleteExtent(roots.iterator().next());
            } catch (InvalidElementException e) {
                LOG.log(Level.WARNING, "Extent deleted a second time");
            }
            roots.clear();
        }
        models.clear();
        diagrams.clear();
        searchpath.clear();

        if (uuidRefs != null) {
            uuidRefs.clear();
        }

        if (defaultModelTypeCache != null) {
