private long fetchLocatedBlocksAndGetLastBlockLength() throws IOException {
    final LocatedBlocks newInfo = dfsClient.getLocatedBlocks(src, 0);
    if (DFSClient.LOG.isDebugEnabled()) {
      DFSClient.LOG.debug("newInfo = " + newInfo);
    }
    if (newInfo == null) {
      throw new IOException("Cannot open filename " + src);
    }

    if (locatedBlocks != null) {
      if (!compareBlockLists(locatedBlocks, newInfo)) {
        throw new IOException("Blocklist for " + src + " has changed!");
      }
    }
    locatedBlocks = newInfo;

    if (!isLastBlockIncomplete(locatedBlocks)) {
      return locatedBlocks.getLastLocatedBlock().getNumBytes();
    }

    final LocatedBlock last = locatedBlocks.getLastLocatedBlock();
    if (last == null) {
      return 0;
    }

    if (last.getLocations().length == 0) {
      return isBlockSizeZero(last) ? 0 : -1;
    }

    final long len = readBlockLength(last);
    last.getBlock().setNumBytes(len);
    return len;
  }

  private boolean compareBlockLists(LocatedBlocks oldInfo, LocatedBlocks newInfo) {
    Iterator<LocatedBlock> oldIter = oldInfo.getLocatedBlocks().iterator();
    Iterator<LocatedBlock> newIter = newInfo.getLocatedBlocks().iterator();
    while (oldIter.hasNext() && newIter.hasNext()) {
      if (!oldIter.next().getBlock().equals(newIter.next().getBlock())) {
        return false;
      }
    }
    return true;
  }

  private boolean isLastBlockIncomplete(LocatedBlocks info) {
    return info != null && !info.isLastBlockComplete();
  }

  private boolean isBlockSizeZero(LocatedBlock last) {
    return last.getBlockSize() == 0;
  }

  /** Read the block length from one of the datanodes. */
  private long readBlockLength(LocatedBlock locatedblock) throws IOException {
    assert locatedblock != null : "LocatedBlock cannot be null";
    int replicaNotFoundCount = locatedblock.getLocations().length;

    for(DatanodeInfo datanode : locatedblock.getLocations()) {
      ClientDatanodeProtocol cdp = null;

      try {
        cdp = DFSUtil.createClientDatanodeProtocolProxy(datanode,
            dfsClient.getConfiguration(), dfsClient.getConf().socketTimeout,
            dfsClient.getConf().connectToDnViaHostname, locatedblock);

        final long n = cdp.getReplicaVisibleLength(locatedblock.getBlock());

        if (n >= 0) {
          return n;
        }
      }
      catch(IOException ioe) {
        if (isReplicaNotFoundException(ioe)) {
          replicaNotFoundCount--;
        }

        if (DFSClient.LOG.isDebugEnabled()) {
          DFSClient.LOG.debug("Failed to getReplicaVisibleLength from datanode "
              + datanode + " for block " + locatedblock.getBlock(), ioe);
        }
      } finally {
        if (cdp != null) {
          RPC.stopProxy(cdp);
        }
      }
    }

    if (replicaNotFoundCount == 0) {
      return 0;
    }

    throw new IOException("Cannot obtain block length for " + locatedblock);
  }

  private boolean isReplicaNotFoundException(IOException ioe) {
    return ioe instanceof RemoteException &&
        (((RemoteException) ioe).unwrapRemoteException() instanceof
            ReplicaNotFoundException);
  }

