/**
 * Attempts to find a suitable datanode descriptor by matching IP or selecting
 * a random node from the appropriate rack or cluster.
 *
 * @param dnId the DatanodeID to match
 * @return the best available DatanodeDescriptor, or null if none found
 */
private DatanodeDescriptor findBestMatchingNodeInCluster(DatanodeID dnId) {
  String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);

  List<Node> rackNodes = getNetworkTopology().getDatanodesInRack(networkLocation);
  DatanodeDescriptor node = null;

  if (rackNodes != null && !rackNodes.isEmpty()) {
    node = findMachineLocalNode(rackNodes, dnId.getIpAddr());
    if (node == null) {
      node = findRandomNode(rackNodes);
    }
  }

  if (node == null) {
    node = (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
  }

  return node;
}

/**
