 * @param ipAddr    IP address to match
 * @return matching DatanodeDescriptor, or null if no match found
 */
private DatanodeDescriptor findMachineLocalNode(List<Node> rackNodes, String ipAddr) {
  for (Node rackNode : rackNodes) {
    DatanodeDescriptor descriptor = (DatanodeDescriptor) rackNode;
    if (descriptor.getIpAddr().equals(ipAddr)) {
