private static class DatanodeIDParser {
  private final String hostLine;
  private String hostStr;
  private int port = DFSConfigKeys.DFS_DATANODE_DEFAULT_PORT;
  private String ipAddr = "";
  private final int httpPort;
  private final int httpsPort;
  private final int ipcPort;

  DatanodeIDParser(String hostLine) {
    this.hostLine = hostLine;
    this.httpPort = DFSConfigKeys.DFS_DATANODE_HTTP_DEFAULT_PORT;
    this.httpsPort = DFSConfigKeys.DFS_DATANODE_HTTPS_DEFAULT_PORT;
    this.ipcPort = DFSConfigKeys.DFS_DATANODE_IPC_DEFAULT_PORT;
  }

  void parse() {
    int idx = hostLine.indexOf(':');
    if (idx == -1) {
      hostStr = hostLine;
    } else {
      hostStr = hostLine.substring(0, idx);
      try {
        port = Integer.parseInt(hostLine.substring(idx + 1));
      } catch (NumberFormatException ignored) {
        // keep default port
      }
    }

    if (InetAddresses.isInetAddress(hostStr)) {
      ipAddr = hostStr;
    } else {
      try {
        ipAddr = InetAddress.getByName(hostStr).getHostAddress();
      } catch (UnknownHostException e) {
        LOG.warn("Invalid hostname " + hostStr + " in hosts file");
      }
    }
  }

  DatanodeID build() {
    parse();
    return new DatanodeID(ipAddr, hostStr, "", port, httpPort, httpsPort, ipcPort);
  }
}

/** Parse a DatanodeID from a hosts file entry. */
private DatanodeID parseDNFromHostsEntry(String hostLine) {
  return new DatanodeIDParser(hostLine).build();
}

