/**
 * Get the best matching DatanodeDescriptor for the given address.
 * Tries exact match first, then host match, then rack-local, and finally any node.
 */
DatanodeDescriptor getDatanodeDescriptor(String address) {
  DatanodeID dnId = parseDNFromHostsEntry(address);
  String host = dnId.getIpAddr();
  int xferPort = dnId.getXferPort();
  DatanodeDescriptor node = getDatanodeByXferAddr(host, xferPort);
  if (node == null) {
    node = getDatanodeByHost(host);
  }
  if (node == null) {
    String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);

    // Try machine local and rack local fallback
    DatanodeSelector selector = new DatanodeSelector(host, networkLocation);
    node = selector.selectRackLocal();
    if (node == null) {
      node = selector.selectAny();
    }
  }
  return node;
}

private static class DatanodeSelector {
  private final String host;
  private final String networkLocation;
  private NetworkTopology topology;

  DatanodeSelector(String host, String networkLocation) {
    this.host = host;
    this.networkLocation = networkLocation;
    this.topology = NetworkTopology.getInstance(new HdfsConfiguration());
  }

  DatanodeDescriptor selectRackLocal() {
    List<Node> rackNodes = topology.getDatanodesInRack(networkLocation);
    if (rackNodes != null) {
      for (Node rackNode : rackNodes) {
        if (((DatanodeDescriptor) rackNode).getIpAddr().equals(host)) {
          return (DatanodeDescriptor) rackNode;
        }
      }
      if (!rackNodes.isEmpty()) {
        return (DatanodeDescriptor) rackNodes.get(
            DFSUtil.getRandom().nextInt(rackNodes.size()));
      }
    }
    return null;
  }

  DatanodeDescriptor selectAny() {
    return (DatanodeDescriptor) topology.chooseRandom(NodeBase.ROOT);
  }
