}

/**
 * Try to find a proxy source on the same rack as the target.
 *
 * @param targetDN the target datanode information
 * @return true if a suitable proxy was found on the same rack
 */
private boolean findProxyOnSameRack(DatanodeInfo targetDN) {
  for (StorageGroup loc : block.getLocations()) {
    if (cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN) && addTo(loc)) {
      return true;
    }
  }
  return false;
}

/**
 * Try to find any available proxy from block locations.
 *
 * @return true if a suitable proxy was found among all locations
 */
private boolean findAnyAvailableProxy() {
  for (StorageGroup loc : block.getLocations()) {
    if (addTo(loc)) {
      return true;
    }
  }
  return false;
}

private boolean chooseProxySource() {
  final DatanodeInfo targetDN = target.getDatanodeInfo();

  if (isSourceAndTargetSameAndAddable(targetDN)) {
    return true;
  }

  if (cluster.isNodeGroupAware()) {
    if (addFromAnyMatchingLocation(loc -> cluster.isOnSameNodeGroup(loc.getDatanodeInfo(), targetDN))) {
      return true;
    }
  }

  if (addFromAnyMatchingLocation(loc -> cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN))) {
    return true;
  }

  return addFromAnyMatchingLocation(loc -> true);
}

private boolean isSourceAndTargetSameAndAddable(DatanodeInfo targetDN) {
  return source.getDatanodeInfo().equals(targetDN) && addTo(source);
}

private boolean addFromAnyMatchingLocation(LocationPredicate predicate) {
  for (StorageGroup loc : block.getLocations()) {
    if (predicate.test(loc) && addTo(loc)) {
      return true;
    }
  }
  return false;
}

@FunctionalInterface
private interface LocationPredicate {
  boolean test(StorageGroup location);
