private boolean isBitSet(int value, int bitIndex) {
    return (value & (1 << bitIndex)) != 0;
}

private void applyInUseMapping(boolean[] inUse, int inUse16) {
    for (int i = 0; i < 16; i++) {
        if (isBitSet(inUse16, i)) {
            int i16 = i << 4;
            for (int j = 0; j < 16; j++) {
                if (bsGetBit()) {
                    inUse[i16 + j] = true;
                }
            }
        }
    }
}

private void processSelectors(int nSelectors, int nGroups, byte[] selector, byte[] selectorMtf, byte[] pos) {
    for (int i = 0; i < nSelectors; i++) {
        int j = 0;
        while (bsGetBit()) {
            j++;
        }
        selectorMtf[i] = (byte) j;
    }

    for (int v = nGroups; --v >= 0;) {
        pos[v] = (byte) v;
    }

    for (int i = 0; i < nSelectors; i++) {
        int v = selectorMtf[i] & 0xff;
        byte tmp = pos[v];
        while (v > 0) {
            pos[v] = pos[v - 1];
            v--;
        }
        pos[0] = tmp;
        selector[i] = tmp;
    }
}

private void receiveCodingTables(int alphaSize, int nGroups, char[][] len) throws IOException {
    for (int t = 0; t < nGroups; t++) {
        int curr = (int) bsR(5);
        char[] len_t = len[t];
        for (int i = 0; i < alphaSize; i++) {
            while (bsGetBit()) {
                curr += bsGetBit() ? -1 : 1;
            }
            len_t[i] = (char) curr;
        }
    }
}

private void recvDecodingTables() throws IOException {
    final Data dataShadow = this.data;
    final boolean[] inUse = dataShadow.inUse;
    final byte[] pos = dataShadow.recvDecodingTables_pos;
    final byte[] selector = dataShadow.selector;
    final byte[] selectorMtf = dataShadow.selectorMtf;

    int inUse16 = 0;

    for (int i = 0; i < 16; i++) {
        if (bsGetBit()) {
            inUse16 |= 1 << i;
        }
    }

    for (int i = 256; --i >= 0;) {
        inUse[i] = false;
    }

    applyInUseMapping(inUse, inUse16);

    makeMaps();
    final int alphaSize = this.nInUse + 2;

    final int nGroups = (int) bsR(3);
    final int nSelectors = (int) bsR(15);

    processSelectors(nSelectors, nGroups, selector, selectorMtf, pos);

    final char[][] len = dataShadow.temp_charArray2d;

    receiveCodingTables(alphaSize, nGroups, len);

    createHuffmanDecodingTables(alphaSize, nGroups);
}

private boolean isBitSet(long value, int bitIndex) {
    return (value & (1L << bitIndex)) != 0;
}

private boolean shouldProcessSelectorByte(int groupPos) {
    return groupPos == 0;
}

private void advanceSelectorGroup(int[] groupNo, int[] groupPos, int selectorIndex) {
    groupPos[0] = G_SIZE - 1;
    groupNo[0] = selectorIndex;
}

private int readBaseValue(int[] base, int zn, long zvec) {
    return base[zn];
}

private int readLimitValue(int[] limit, int zn) {
    return limit[zn];
}

private int adjustCurrent(int current, boolean increment) {
    return increment ? current + 1 : current - 1;
}

private boolean shouldContinueWhileLoop(boolean condition1, boolean condition2) {
    return condition1 && condition2;
}

private boolean shouldContinueForLoop(int i, int alphaSize) {
    return i < alphaSize;
}

private boolean isRandomizedBlock(boolean blockRandomised) {
    return blockRandomised;
}

private boolean isValidStreamPosition(int origPtr, int[] tt) {
    return origPtr >= 0 && origPtr < tt.length;
}

private boolean shouldUpdateState(STATE currentState, STATE targetState) {
    return currentState != targetState;
}

private boolean isEndOfBlock(int nextSym, int eob) {
    return nextSym == eob;
}

private boolean isEndOfStream(int thech) {
    return thech < 0;
}

private boolean isBlockOverrun(int lastShadow, int limitLast) {
    return lastShadow >= limitLast;
}

private boolean shouldUseFastCopy(int nextSym, int threshold) {
    return nextSym <= threshold;
}

private boolean isByteUsed(boolean[] inUse, int index) {
    return inUse[index];
}

private boolean hasAvailableBits(int bsLive, int requiredBits) {
    return bsLive >= requiredBits;
}

private boolean shouldProcessGroupPos(int groupPos) {
    return groupPos == 0;
}

private boolean isInRange(int value, int min, int max) {
    return value >= min && value <= max;
}

private boolean isBitNotSet(int value, int bit) {
    return (value & (1 << bit)) == 0;
}

private boolean isGroupPositionZero(int groupPos) {
    return groupPos == 0;
}

private boolean isCurrentCharEqualToPrevious(int current, int previous) {
    return current == previous;
}

private boolean shouldInitialize>DataShadow(Data dataShadow) {
    return dataShadow == null;
}

private boolean shouldUpdateBlockState(READ_MODE readMode, STATE currentState) {
    return readMode == READ_MODE.CONTINUOUS && currentState != STATE.EOF;
}

