public RemoteIterator<LocatedFileStatus> listFiles(
    final Path f, final boolean recursive) throws AccessControlException,
    FileNotFoundException, UnsupportedFileSystemException, 
    IOException {
  return new RemoteIterator<LocatedFileStatus>() {
    private final Stack<RemoteIterator<LocatedFileStatus>> iterators = 
        new Stack<RemoteIterator<LocatedFileStatus>>();
    private RemoteIterator<LocatedFileStatus> currentIterator;
    private LocatedFileStatus currentFile;

    {
      currentIterator = listLocatedStatus(f);
    }

    @Override
    public boolean hasNext() throws IOException {
      advanceIterator();
      return currentFile != null;
    }

    @Override
    public LocatedFileStatus next() throws IOException {
      if (!hasNext()) {
        throw new java.util.NoSuchElementException("No more entry in " + f);
      }
      LocatedFileStatus result = currentFile;
      currentFile = null;
      return result;
    }

    private void advanceIterator() throws IOException {
      while (currentFile == null && (currentIterator != null || !iterators.isEmpty())) {
        if (currentIterator == null || !currentIterator.hasNext()) {
          if (!iterators.isEmpty()) {
            currentIterator = iterators.pop();
          } else {
            currentIterator = null;
            continue;
          }
        }

        if (currentIterator != null && currentIterator.hasNext()) {
         LocatedFileStatus stat = currentIterator.next();
          processFileStat(stat, recursive);
        }
      }
    }

    private void processFileStat(LocatedFileStatus stat, boolean recursive) 
        throws IOException {
      if (stat.isFile()) {
        currentFile = stat;
      } else if (stat.isSymlink()) {
        resolveAndProcessSymlink(stat, recursive);
      } else if (recursive && stat.isDirectory()) {
        pushIterator(stat.getPath());
      }
    }

    private void resolveAndProcessSymlink(LocatedFileStatus stat, 
        boolean recursive) throws IOException {
      try {
        FileStatus resolved = FileContext.this.getFileStatus(stat.getSymlink());
        if (resolved.isFile() || (recursive && resolved.isDirectory())) {
          pushIterator(stat.getPath());
        }
      } catch (IOException e) {
        // Skip symlink if resolution fails
      }
    }

    private void pushIterator(Path path) throws IOException {
      iterators.push(currentIterator);
      currentIterator = listLocatedStatus(path);
    }
  };
}

class Dumper implements Runnable {
    /** Dump data into a file */
    private void dump() {
      if (!isDumpEnabled()) {
        return;
      }

      initializedumpOut();
      initializeRaf();

      if (LOG.isDebugEnabled()) {
        LOG.debug("Start dump. Before dump, nonSequentialWriteInMemory == "
            + nonSequentialWriteInMemory.get());
      }

      Iterator<OffsetRange> it = pendingWrites.keySet().iterator();
      while (activeState && it.hasNext()
          && nonSequentialWriteInMemory.get() > 0) {
        OffsetRange key = it.next();
        WriteCtx writeCtx = pendingWrites.get(key);
        if (writeCtx == null) {
          continue;
        }
        try {
          long dumpedDataSize = writeCtx.dumpData(dumpOut, raf);
          if (dumpedDataSize > 0) {
            updateNonSequentialWriteInMemory(-dumpedDataSize);
          }
        } catch (IOException e) {
          handleDumpFailure(e, writeCtx);
          return;
        }
      }

      if (LOG.isDebugEnabled()) {
        LOG.debug("After dump, nonSequentialWriteInMemory == "
            + nonSequentialWriteInMemory.get());
      }
    }

    private void initializedumpOut() {
      if (dumpOut == null) {
        LOG.info("Create dump file: " + dumpFilePath);
        File dumpFile = new File(dumpFilePath);
        try {
          synchronized (this) {
            if (!dumpFile.exists()) {
              Preconditions.checkState(dumpFile.createNewFile(),
                  "The dump file should not exist: %s", dumpFilePath);
              dumpOut = new FileOutputStream(dumpFile);
            }
          }
        } catch (IOException e) {
          LOG.error("Got failure when creating dump stream " + dumpFilePath, e);
          enabledDump = false;
          closeDumpOutQuietly();
        }
      }
    }

    private void initializeRaf() {
      if (raf == null) {
        try {
          raf = new RandomAccessFile(dumpFilePath, "r");
        } catch (FileNotFoundException e) {
          LOG.error("Can't get random access to file " + dumpFilePath);
          enabledDump = false;
        }
      }
    }

    private void closeDumpOutQuietly() {
      if (dumpOut != null) {
        try {
          dumpOut.close();
        } catch (IOException e1) {
          LOG.error("Can't close dump stream " + dumpFilePath, e1);
        }
        dumpOut = null;
      }
    }

    private void handleDumpFailure(IOException e, WriteCtx writeCtx) {
      LOG.error("Dump data failed: " + writeCtx + " with error: " + e
          + " OpenFileCtx state: " + activeState);
      enabledDump = false;
    }

    @Override
    public void run() {
      while (activeState && enabledDump) {
        try {
          if (nonSequentialWriteInMemory.get() >= DUMP_WRITE_WATER_MARK) {
            dump();
          }
          synchronized (OpenFileCtx.this) {
            if (nonSequentialWriteInMemory.get() < DUMP_WRITE_WATER_MARK) {
              OpenFileCtx.this.notifyAll();
              try {
                OpenFileCtx.this.wait();
                if (LOG.isDebugEnabled()) {
                  LOG.debug("Dumper woke up");
                }
              } catch (InterruptedException e) {
                LOG.info("Dumper is interrupted, dumpFilePath= "
                    + OpenFileCtx.this.dumpFilePath);
              }
            }
          }
          if (LOG.isDebugEnabled()) {
            LOG.debug("Dumper checking OpenFileCtx activeState: " + activeState
                + " enabledDump: " + enabledDump);
          }
        } catch (Throwable t) {
          // unblock threads with new request
          synchronized (OpenFileCtx.this) {
            OpenFileCtx.this.notifyAll();
          }
          LOG.info("Dumper get Throwable: " + t + ". dumpFilePath: "
              + OpenFileCtx.this.dumpFilePath, t);
          activeState = false;
        }
      }
    }
  }

