// Helper methods to reduce cognitive complexity
/**
 * Determines whether key event processing should be skipped
 */
private boolean shouldSkipProcessing(KeyEvent evt)
{
	JComponent focusOwner = getFocusOwnerAsJComponent();
	if (focusOwner != null && skipProcessingForComponent(focusOwner, evt))
		return true;

	JTextComponent textComp = getFocusOwnerAsTextComponent();
	if (textComp != null && skipProcessingForTextComponent(textComp, evt))
		return true;

	return evt.isConsumed();
}

/**
 * Returns the focus owner as a JComponent if applicable
 */
private JComponent getFocusOwnerAsJComponent()
{
	Object owner = getFocusOwner();
	return (owner instanceof JComponent) ? (JComponent)owner : null;
}

/**
 * Returns the focus owner as a JTextComponent if applicable
 */
private JTextComponent getFocusOwnerAsTextComponent()
{
	Object owner = getFocusOwner();
	return (owner instanceof JTextComponent) ? (JTextComponent)owner : null;
}

/**
 * Checks whether key event should be skipped for JComponent
 */
private boolean skipProcessingForComponent(JComponent comp, KeyEvent evt)
{
	InputMap map = comp.getInputMap();
	ActionMap am = comp.getActionMap();

	if(map == null || am == null || !comp.isEnabled())
		return false;

	Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
	return binding != null && am.get(binding) != null;
}

/**
 * Checks whether key event should be skipped for JTextComponent
 */
private boolean skipProcessingForTextComponent(JTextComponent comp, KeyEvent evt)
{
	if(evt.getID() != KeyEvent.KEY_PRESSED)
		return false;

	switch(evt.getKeyCode())
	{
	case KeyEvent.VK_BACK_SPACE:
	case KeyEvent.VK_TAB:
	case KeyEvent.VK_ENTER:
		return true;
	}

	Keymap keymap = comp.getKeymap();
	return keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null;
}

