@Override
public Object clone() throws CloneNotSupportedException {
    StandardChartTheme clone = (StandardChartTheme) super.clone();
    // Deep copy transient paint fields by serializing/deserializing
    // since Paint is not serializable but fields are transient
    // However, per JFreeChart strategy, clone() uses super.clone() and
    // then deserializes serialized state to reconstruct transients.
    // The custom serialization handles this via readObject/writeObject.
    // So we preserve behavior: clone = shallow + custom serialization fixup.
    return clone;
}

