@Override
public Object clone() throws CloneNotSupportedException {
    ContourPlot clone = (ContourPlot) super.clone();
    clone-copyFields(clone);
    return clone;
}

/**
 * Copies all field values from the receiver to the <code>clone</code>, handling
 * deep clones and necessary listener re-registration.
 * @param clone the already-shallow-cloned ContourPlot instance to populate
 */
private void clone-copyFields(ContourPlot clone) {
    clone.domainAxis = cloneCopyAxis(this.domainAxis, clone);
    clone.rangeAxis = cloneCopyAxis(this.rangeAxis, clone);
    if (clone.dataset != null) {
        clone.dataset.addChangeListener(clone);
    }
    clone.colorBar = cloneCopyColorBar(this.colorBar);
    clone.domainMarkers = cloneCopyMarkers(this.domainMarkers);
    clone.rangeMarkers = cloneCopyMarkers(this.rangeMarkers);
    clone.annotations = cloneCopyAnnotations(this.annotations);
    clone.clipPath = cloneCopyClipPath(this.clipPath);
}

/**
 * Deep clones a ValueAxis and re-registers listeners on the clone.
 * @param axis the source axis (may be null)
 * @param plot the clone plot instance
 * @return the cloned axis or null
 */
private ValueAxis cloneCopyAxis(ValueAxis axis, ContourPlot plot) {
    if (axis == null) {
        return null;
    }
    try {
        ValueAxis cloned = (ValueAxis) axis.clone();
        cloned.setPlot(plot);
        cloned.addChangeListener(plot);
        return cloned;
    } catch (CloneNotSupportedException ex) {
        throw new RuntimeException("Failed to clone axis", ex);
    }
}

/**
 * Deep clones the ColorBar (may be null).
 * @param colorBar the source color bar
 * @return the cloned color bar or null
 */
private ColorBar cloneCopyColorBar(ColorBar colorBar) {
    if (colorBar == null) {
        return null;
    }
    try {
        return (ColorBar) colorBar.clone();
    } catch (CloneNotSupportedException ex) {
        throw new RuntimeException("Failed to clone color bar", ex);
    }
}

/**
 * Deep clones a list of markers.
 * @param markers the source marker list (may be null)
 * @return a new list with cloned markers, or null
 */
private List cloneCopyMarkers(List markers) {
    if (markers == null) {
        return null;
    }
    return (List) ObjectUtilities.deepClone(markers);
}

/**
 * Deep clones a list of annotations.
