    def _extractCompressionOffset(self, strio, visited, off):
        """
        Extract and validate a DNS compression pointer offset.

        @type strio: file
        @param strio: The stream to read from.

        @type visited: set
        @param visited: Set of already-visited offsets to detect loops.

        @type off: int
        @param off: Current offset if already in a compression chain, else 0.

        @raise ValueError: If a compression loop is detected.

        @return: The validated compression offset.
        """
        new_off = ((ord(readPrecisely(strio, 1)) & 63) << 8
                   | ord(readPrecisely(strio, 1)))
        if new_off in visited:
            raise ValueError("Compression loop in encoded name")
        visited.add(new_off)
        return new_off


